import 'package:go_router/go_router.dart';import 'package:flutter/material.dart';import 'package:uuid/uuid.dart';import '../../models/party.dart';import '../../services/demo_store.dart';
class CreatePartyScreen extends StatefulWidget{const CreatePartyScreen({super.key});@override State<CreatePartyScreen>createState()=>_CreatePartyScreenState();}
class _CreatePartyScreenState extends State<CreatePartyScreen>{final title=TextEditingController(),desc=TextEditingController();String category='photography',style='digital',privacy='public';int mins=60;DateTime start=DateTime.now().toUtc();bool saving=false;@override void dispose(){title.dispose();desc.dispose();super.dispose();}Future<void>save()async{if(title.text.trim().isEmpty)return;setState(()=>saving=true);final p=Party(id:const Uuid().v4(),ownerId:'demo-user',title:title.text.trim(),description:desc.text.trim(),category:category,contentLanguage:'en',countdownStyle:style,privacy:privacy,startAt:start,endAt:start.add(Duration(minutes:mins)),status:start.isAfter(DateTime.now().toUtc())?'scheduled':'live',createdAt:DateTime.now().toUtc(),lastActivityAt:DateTime.now().toUtc());DemoStore.instance.addParty(p);if(mounted){setState(()=>saving=false);GoRouter.of(context).pushReplacement('/party/${p.id}');}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Create Party')),body:ListView(padding:const EdgeInsets.all(20),children:[TextField(controller:title,maxLength:80,decoration:const InputDecoration(labelText:'Theme title',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:desc,maxLength:500,maxLines:4,decoration:const InputDecoration(labelText:'Description',border:OutlineInputBorder())),const SizedBox(height:12),DropdownButtonFormField(value:category,items:['travel','food','music','fashion','art','sports','nature','pets','party','lifestyle','photography','other'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>category=v!),decoration:const InputDecoration(labelText:'Category')),const SizedBox(height:12),DropdownButtonFormField(value:style,items:['digital','motor','rock','gothic','sweet','cartoon','dream','cinema','flip','minimal','festival','cyber'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>style=v!),decoration:const InputDecoration(labelText:'Countdown style')),const SizedBox(height:12),DropdownButtonFormField(value:privacy,items:['public','unlisted','private'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>privacy=v!),decoration:const InputDecoration(labelText:'Privacy')),const SizedBox(height:12),DropdownButtonFormField<int>(value:mins,items:[1,5,10,15,30,60,120,360,720,1440,2880,10080,43200].map((x)=>DropdownMenuItem(value:x,child:Text(x<60?'$x minutes':x<1440?'${x~/60} hours':'${x~/1440} days'))).toList(),onChanged:(v)=>setState(()=>mins=v!),decoration:const InputDecoration(labelText:'Duration')),const SizedBox(height:24),FilledButton.icon(onPressed:saving?null:save,icon:const Icon(Icons.celebration),label:Text(saving?'Creating…':'CREATE PARTY'))]));}
